package net.officefloor.hq.app.pool;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PoolRepository extends JpaRepository<Pool, Long> {

    /** The sheet's pools, in the order they were added. */
    List<Pool> findBySheetIdOrderByIdAsc(String sheetId);

    Optional<Pool> findByIdAndSheetId(Long id, String sheetId);

    boolean existsBySheetIdAndName(String sheetId, String name);
}
package net.officefloor.hq.app.pool;

/** A pool that cannot be added (a blank name, or one already taken), or a member that cannot be added to
 *  one (a person already in it, a share that is not more than 0.00 and at most 100.00 in two decimals, or a
 *  pool that would contain itself, is already in a pool, or would make a chain of pools more than three deep). */
public class PoolRefusedException extends RuntimeException {

    public PoolRefusedException(String message) {
        super(message);
    }
}
-- The sheet's pools: a name (trimmed, once per sheet) and members, each a person of the sheet with a share
-- percent (more than 0.00, at most 100.00). A person is in a pool at most once, and may be in several pools.
CREATE TABLE pool (
    id       BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    UNIQUE (sheet_id, name)
);

CREATE TABLE pool_member (
    id        BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pool_id   BIGINT       NOT NULL REFERENCES pool (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    share     NUMERIC(5,2) NOT NULL CHECK (share > 0 AND share <= 100),
    UNIQUE (pool_id, person_id)
);

